const captureQuery=new URLSearchParams(location.search);
const shareSessionKey='unbound-save-to-ideas-intake';
let incomingShare=(captureQuery.has('url')||captureQuery.has('text')||captureQuery.has('title'))?parseShareTarget(captureQuery):null;
if(incomingShare){try{sessionStorage.setItem(shareSessionKey,JSON.stringify(incomingShare));}catch{}}
if(!incomingShare){try{const pending=JSON.parse(sessionStorage.getItem(shareSessionKey)||'null');if(pending?.fromShare)incomingShare=pending;}catch{}}
const launchSaveToIdeas=captureQuery.has('saveToIdeas')||!!incomingShare?.fromShare;
let launchQuickCapture=captureQuery.has('quickCapture')||launchSaveToIdeas;
if(launchQuickCapture)document.body.classList.add('quick-capture-launch');
let quickCaptureController=null;

