let calendarHighlightEnabled=false,calendarHighlightColour='#f4d36c',calendarHighlightCleanup=()=>{};
function calendarHighlightMarkup(){return `<div class="calendar-highlight-tools"><button type="button" data-action="highlight-toggle" aria-pressed="${calendarHighlightEnabled}" aria-expanded="false" aria-controls="calendar-highlight-picker">${calendarHighlightEnabled?'‚úì Done':'‚úé Highlight'}</button><div id="calendar-highlight-picker" class="calendar-highlight-picker" role="group" aria-label="Highlight options" hidden><div class="highlight-colours">${[["Gold","#f4d36c"],["Sage","#91a58f"],["Blue","#9bb3c9"],["Lavender","#b5a7c6"],["Rose","#bf9ba5"],["Tan","#bea185"]].map(([name,colour])=>`<button type="button" data-highlight-swatch="${colour}" aria-label="${name} highlight" title="${name}" style="--swatch:${colour}"><span aria-hidden="true"></span>${name}</button>`).join('')}</div><div class="highlight-picker-actions"><label>Custom colour <input type="color" data-highlight-colour value="${calendarHighlightColour}" aria-label="Highlight colour"></label><button type="button" data-action="highlight-undo">Undo</button><button type="button" data-action="highlight-clear">Erase highlights</button></div></div></div>`;}

function setupCalendarHighlight(){
 calendarHighlightCleanup();
 const canvas=document.querySelector('#calendar-highlight-canvas'),page=canvas?.closest('.calendar-highlight-surface');if(!canvas||!page)return;
 const key='calendar-highlight:'+view+':'+(view==='year'?year():view==='month'?date.slice(0,7):view==='week'?monday(date):date);
 let strokes=structuredClone(state.ink[key]||[]),active=null;
 const draw=()=>{const rect=page.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.round(rect.width*dpr));canvas.height=Math.max(1,Math.round(rect.height*dpr));const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.lineCap='round';ctx.lineJoin='round';ctx.globalAlpha=.34;ctx.lineWidth=17;for(const stroke of strokes){ctx.strokeStyle=stroke.color;ctx.beginPath();stroke.points.forEach((p,i)=>i?ctx.lineTo(p.x*rect.width,p.y*rect.height):ctx.moveTo(p.x*rect.width,p.y*rect.height));ctx.stroke();}ctx.globalAlpha=1;};
 const resize=new ResizeObserver(draw),listeners=new AbortController();resize.observe(page);calendarHighlightCleanup=()=>{resize.disconnect();listeners.abort();};draw();
 const point=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};};
 canvas.style.pointerEvents=calendarHighlightEnabled?'auto':'none';canvas.style.touchAction=calendarHighlightEnabled?'none':'auto';
 canvas.onpointerdown=e=>{if(!calendarHighlightEnabled||active||e.button>0)return;e.preventDefault();e.stopPropagation();canvas.setPointerCapture(e.pointerId);active={color:calendarHighlightColour,points:[point(e)]};strokes.push(active);draw();};
 canvas.onpointermove=e=>{if(active&&canvas.hasPointerCapture(e.pointerId)){active.points.push(point(e));draw();}};
 canvas.onpointerup=canvas.onpointercancel=e=>{if(active&&canvas.hasPointerCapture(e.pointerId)){active=null;state.ink[key]=strokes;save();}};
 const toolbar=page.parentElement.querySelector('.calendar-highlight-tools'),toggle=toolbar.querySelector('[data-action="highlight-toggle"]'),picker=toolbar.querySelector('#calendar-highlight-picker');
 const closePicker=()=>{picker.hidden=true;toggle.setAttribute('aria-expanded','false');};
 const setEnabled=enabled=>{calendarHighlightEnabled=enabled;canvas.style.pointerEvents=enabled?'auto':'none';canvas.style.touchAction=enabled?'none':'auto';toggle.setAttribute('aria-pressed',String(enabled));toggle.textContent=enabled?'‚úì Done':'‚úé Highlight';closePicker();};
 toolbar.querySelector('[data-action="highlight-undo"]').addEventListener('click',()=>{strokes.pop();state.ink[key]=strokes;save();draw();});
 toolbar.querySelector('[data-action="highlight-clear"]').addEventListener('click',()=>{strokes=[];state.ink[key]=[];save();draw();});
 const chooseColour=colour=>{calendarHighlightColour=colour;toolbar.querySelector('[data-highlight-colour]').value=colour;setEnabled(true);toggle.focus({preventScroll:true});};
 toolbar.querySelectorAll('[data-highlight-swatch]').forEach(button=>button.addEventListener('click',()=>chooseColour(button.dataset.highlightSwatch)));
 toolbar.querySelector('[data-highlight-colour]').addEventListener('change',e=>chooseColour(e.target.value));
 toggle.addEventListener('click',()=>{if(calendarHighlightEnabled){setEnabled(false);return;}const open=picker.hidden;picker.hidden=!open;toggle.setAttribute('aria-expanded',String(open));});
 document.addEventListener('click',e=>{if(!toolbar.contains(e.target))closePicker();},{signal:listeners.signal});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!picker.hidden){closePicker();toggle.focus({preventScroll:true});}},{signal:listeners.signal});
}

function setupDayInk(){
 const canvas=document.querySelector('#day-ink-canvas'),surface=canvas?.parentElement;if(!canvas||!surface)return;
 const key=`day:${date}:ink`,paths=(state.ink[key]||[]).map(normaliseStroke),clearButton=surface.querySelector('[data-clear-day-ink]');let active=null;
 const draw=()=>{const r=surface.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);paths.forEach(p=>drawInkStroke(ctx,p,r.width,r.height));if(clearButton)clearButton.disabled=!paths.length;};
 const point=e=>{const r=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),p:e.pressure||.5};};
 const update=()=>{const enabled=document.body.classList.contains('day-pencil-mode');canvas.style.pointerEvents=enabled?'auto':'none';canvas.style.touchAction=enabled?'none':'auto';};
 new ResizeObserver(draw).observe(surface);draw();update();
 canvas.onpointerdown=e=>{const isPenInput=e.pointerType==='pen'||e.pointerType==='touch'&&e.buttons===1;if(canvas.style.pointerEvents!=='auto'||!isPenInput||e.button>0||active)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);active=normaliseStroke({tool:'pen',color:state.settings.noteColour||state.settings.ink||'#313a41',size:state.settings.noteSize||3,points:[point(e)]});paths.push(active);state.ink[key]=paths;save();draw();};
 canvas.onpointermove=e=>{if(!active||!canvas.hasPointerCapture(e.pointerId))return;e.preventDefault();for(const sample of (e.getCoalescedEvents?.()?.length?e.getCoalescedEvents():[e]))active.points.push(point(sample));draw();};
 canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=e=>{if(!active)return;active=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);state.ink[key]=paths;save();draw();};
 setupDayInk.update=update;
}

