function validateBackup(data){delete data._cloud;if(data.bookmarks===undefined)data.bookmarks=[];if(data.collections===undefined)data.collections=[];if(!Array.isArray(data.collections)||data.collections.some(collection=>!collection||typeof collection.id!=='string'||!collection.id||typeof collection.name!=='string'||!collection.name.trim()))throw Error('Invalid collections.');if(!Array.isArray(data.bookmarks)||data.bookmarks.some(r=>!r||typeof r.name!=='string'||!/^[-a-zA-Z0-9]+$/.test(r.id)||!/^#[a-f0-9]{6}$/i.test(r.color)||!r.page||!/^\d{4}-\d{2}-\d{2}$/.test(r.page.date)||!['calendar','goals','tasks','notes','habits','reflection','launchpad'].includes(r.page.section)||!['day','week','month','year'].includes(r.page.view)))throw Error('Invalid bookmark ribbons.');if(data.version!==1)throw Error('Unsupported backup format.');for(const key of ['events','tasks','notes','collections','habits','trash','cachedGoogle','googleCalendars'])if(!Array.isArray(data[key]))throw Error(`Missing ${key}.`);if(!data.entries||typeof data.entries!=='object'||Array.isArray(data.entries)||!data.settings||!data.ink)throw Error('Invalid notebook data.');for(const e of [...data.events,...data.cachedGoogle])if(typeof e.id!=='string'||typeof e.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(e.date))throw Error('Invalid appointment.');for(const t of data.tasks)if(typeof t.id!=='string'||typeof t.title!=='string')throw Error('Invalid task.');for(const n of data.notes)if(typeof n.id!=='string'||typeof n.title!=='string')throw Error('Invalid note.');for(const h of data.habits)if(typeof h.title!=='string'||!Array.isArray(h.checks))throw Error('Invalid habit.');for(const value of Object.values(data.entries))if(typeof value!=='string')throw Error('Invalid writing.');if(!Array.isArray(data.settings.favorites)||!Array.isArray(data.settings.selectedCalendars))throw Error('Invalid preferences.');if(data.settings.customCover&&!/^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/.test(data.settings.customCover))throw Error('Invalid cover image.');if(!/^#[0-9a-fA-F]{6}$/.test(data.settings.ink)||data.settings.coverInk&&!/^#[0-9a-fA-F]{6}$/.test(data.settings.coverInk))throw Error('Invalid ink colour.');if(![...Array(coverNames.length).keys(),'custom'].includes(data.settings.cover))throw Error('Invalid cover.');data.settings.font='Caveat';}
