function writingFields(root){return [...root.querySelectorAll('textarea,input:not([type]),input[type="text"],input[type="search"]')].filter(f=>!f.disabled&&!f.readOnly&&!f.hasAttribute('data-no-writing-tools')&&!f.closest('[inert]'));}
